import { createHash } from 'node:crypto';
import { BOOTSTRAP_ONCE, bootstrapScopes, workspace, taskNode, colors } from './model.js';
import type { TaskRow, TaskScope } from './model.js';
import { SQL } from './sql.js';
import { Store } from './store.js';
export function bootstrap(store: Store, scopes: TaskScope[], active: TaskRow[]): void {
  const eligible = bootstrapScopes(scopes);
  if (!eligible.length || store.get(SQL.bootstrapped)) return;
  const byWorkspace = new Map<string, TaskRow[]>();
  for (const row of active) { const bucket = byWorkspace.get(row.workspace_key) ?? []; bucket.push(row); byWorkspace.set(row.workspace_key, bucket); }
  const now = Date.now(), marker = store.database().prepare(SQL.marker);
  if (!byWorkspace.size) { marker.run(BOOTSTRAP_ONCE, now, now); return; }
  const ordered = new Set(store.all<{ node_key: string }>(SQL.groupOrderKeys).map(row => row.node_key));
  let maximum = store.get<{ max_sort_order: number | null }>(SQL.maximum)?.max_sort_order ?? 0;
  const group = store.database().prepare(SQL.bootstrapGroup), order = store.database().prepare(SQL.bootstrapOrder);
  const removeMember = store.database().prepare(SQL.bootstrapRemoveMember), member = store.database().prepare(SQL.bootstrapMember);
  const removeOrder = store.database().prepare(SQL.bootstrapRemoveOrder), workspaceMarker = store.database().prepare(SQL.workspaceMarker);
  store.transaction(() => {
    marker.run(BOOTSTRAP_ONCE, now, now);
    for (const scope of eligible) {
      const key = workspace(scope), rows = byWorkspace.get(key);
      if (!rows?.length) continue;
      rows.sort((a, b) => b.updated_at - a.updated_at || b.created_at - a.created_at || a.task_id.localeCompare(b.task_id));
      const hash = createHash('sha256').update(key).digest('hex'), id = 'workspace-group-' + hash.slice(0, 24);
      const stripped = scope.workspacePath.replace(/[\\/]+$/, ''), segments = stripped.split(/[\\/]/).filter(Boolean);
      const title = segments[segments.length - 1]?.trim() || stripped.trim() || 'Workspace';
      const color = colors[1 + parseInt(hash.slice(0, 2), 16) % 6] ?? 'gray';
      group.run(id, title, color, now, now);
      if (!ordered.has(id)) { maximum += 1000; order.run(id, maximum, now, now); ordered.add(id); }
      rows.forEach((row, index) => {
        removeMember.run(row.workspace_key, row.task_id);
        member.run(id, row.workspace_key, row.workspace_path, row.workspace_identity, row.task_id, (index + 1) * 1000, now, now, now);
        removeOrder.run(taskNode(workspace({ workspacePath: row.workspace_path, workspaceIdentity: row.workspace_identity ?? undefined }), row.task_id));
      });
      workspaceMarker.run(key, id, now, now);
    }
    store.exec(SQL.emptyGroups); store.exec(SQL.danglingGroups);
  });
}

import type { KnorviaProvider } from '@knorvia/shared';
import type { KnorviaGroupedTaskView, KnorviaGroupedTaskViewOrderInput, KnorviaGroupedTaskViewTopLevelNodeRef } from '#src/session/taskListTypes.js';
import { BOOTSTRAP_ONCE, entity, scopeKeys, taskNode, workspace } from './model.js';
import type { TaskRef, TaskRow } from './model.js';
import { GroupView } from './group-view.js';
import { Store } from './store.js';
import { SQL, fill } from './sql.js';
export class GroupOrder {
  constructor(private store: Store, private view: GroupView) {}
  async apply(input: KnorviaGroupedTaskViewOrderInput & { provider?: KnorviaProvider }): Promise<KnorviaGroupedTaskView> {
    await this.store.ready(); const keys = scopeKeys(input.workspaceScopes), scope = new Set(keys), now = Date.now();
    const groupIds = new Set(this.store.all<{ group_id: string }>(SQL.groupIds).map(row => row.group_id));
    const requireGroup = (id: string) => { if (!groupIds.has(id)) throw new Error('Grouped task order 包含不存在的 group'); };
    const validate = (ref: TaskRef): TaskRow | null => {
      if (!scope.has(workspace(ref))) throw new Error('Grouped task order 包含当前 scope 外的 task');
      const row = this.store.read(ref);
      if (!row || row.deleted === 1 || row.archived === 1 || row.pinned === 1) throw new Error('Grouped task order 包含不可见 task');
      return input.provider && row.provider !== input.provider ? null : row;
    };
    const top: KnorviaGroupedTaskViewTopLevelNodeRef[] = [], topTasks = new Set<string>();
    for (const node of input.topLevelNodes) {
      if (node.type === 'group') { requireGroup(node.groupId); top.push(node); }
      else {
        const row = validate(node.task); if (!row) continue;
        topTasks.add(entity(workspace(node.task), node.task.taskId)); top.push(node);
      }
    }
    const grouped = new Set<string>(), groups: Array<{ id: string; tasks: TaskRow[] }> = [];
    for (const group of input.groups) {
      requireGroup(group.groupId); const tasks: TaskRow[] = [];
      for (const ref of group.taskRefs) {
        const row = validate(ref); if (!row) continue;
        const key = entity(workspace(ref), ref.taskId);
        if (grouped.has(key)) throw new Error('Grouped task order 不能让同一个 task 进入多个 group');
        grouped.add(key); tasks.push(row);
      }
      groups.push({ id: group.groupId, tasks });
    }
    const scopedTasks = keys.length ? this.store.all<{ workspace_key: string; task_id: string }>(fill(SQL.scopeTasks, keys.map(() => '?').join(', ')), ...keys) : [];
    this.store.transaction(() => {
      this.store.database().prepare(SQL.orderMarker).run(BOOTSTRAP_ONCE, now, now);
      const remove = this.store.database().prepare(SQL.removeMember), member = this.store.database().prepare(SQL.orderMember);
      for (const key of topTasks) {
        const [workspaceKey, taskId] = key.split('\u0000');
        if (!workspaceKey || !taskId) throw new Error('Grouped task order 顶层 task key 非法');
        remove.run(workspaceKey, taskId);
      }
      for (const group of groups) group.tasks.forEach((row, index) => {
        member.run(group.id, row.workspace_key, row.workspace_path, row.workspace_identity ?? null, row.task_id, (index + 1) * 1000, now, now, now);
      });
      this.store.exec(SQL.removeAllGroupOrders);
      const deleteOrder = this.store.database().prepare(SQL.removeTaskOrder);
      for (const row of scopedTasks) {
        const [workspaceKey, taskId] = entity(row.workspace_key, row.task_id).split('\u0000');
        if (!workspaceKey || !taskId) continue;
        deleteOrder.run(taskNode(workspaceKey, taskId), workspaceKey);
      }
      const insert = this.store.database().prepare(SQL.insertOrder);
      top.forEach((node, index) => {
        const key = node.type === 'group' ? node.groupId : taskNode(workspace(node.task), node.task.taskId);
        insert.run(node.type, key, (index + 1) * 1000, now, now);
      });
    });
    return await this.view.query({ workspaceScopes: input.workspaceScopes, provider: input.provider });
  }
}

import { CRON_DEFAULT_GROUP_ID } from '@knorvia/shared';
import type { KnorviaProvider } from '@knorvia/shared';
import type { KnorviaGroupedTaskView, KnorviaGroupedTaskViewNode, KnorviaGroupedTaskViewQuery, KnorviaGroupedTaskViewStructure, KnorviaGroupedTaskViewStructureTopOrder, KnorviaTaskListItem } from '#src/session/taskListTypes.js';
import { bootstrap } from './bootstrap.js';
import { entity, groupMeta, scopeKeys, taskNode, workspace } from './model.js';
import type { GroupRow, MemberRow, OrderRow, TaskRow, TaskScope } from './model.js';
import { Store } from './store.js';
import { TaskQueries } from './task-queries.js';
import { SQL, fill } from './sql.js';
function itemKey(item: KnorviaTaskListItem): string { return entity(workspace(item), item.taskId); }
function nodeKey(node: KnorviaGroupedTaskViewNode): string { return node.type === 'group' ? 'group:' + node.group.id : 'task:' + taskNode(workspace(node.task), node.task.taskId); }
export class GroupView {
  constructor(private store: Store, private tasks: TaskQueries) {}
  private visibleGroups(keys: Set<string>): GroupRow[] {
    const bootstraps = new Map(this.store.all<{ workspace_key: string; group_id: string }>(SQL.bootstrapGroups).map(row => [row.group_id, row.workspace_key]));
    return this.store.all<GroupRow>(SQL.groups).filter(row => !bootstraps.has(row.group_id) || keys.has(bootstraps.get(row.group_id)!));
  }
  async structure(input: { workspaceScopes: Array<{ workspacePath: string; workspaceIdentity?: string }> }): Promise<KnorviaGroupedTaskViewStructure> {
    await this.store.ready();
    const groups = this.visibleGroups(new Set(scopeKeys(input.workspaceScopes))).map(groupMeta);
    const members = this.store.all<MemberRow>(SQL.members).map(row => ({
      groupId: row.group_id, workspaceKey: row.workspace_key, workspacePath: row.workspace_path,
      ...(row.workspace_identity ? { workspaceIdentity: row.workspace_identity } : {}),
      taskId: row.task_id, sortOrder: row.sort_order, addedAt: row.added_at,
    }));
    const topLevelOrders: KnorviaGroupedTaskViewStructureTopOrder[] = [];
    for (const row of this.store.all<OrderRow>(SQL.orders)) {
      if (row.node_type === 'group') { topLevelOrders.push({ type: 'group', groupId: row.node_key, sortOrder: row.sort_order }); continue; }
      try {
        const ref: unknown = JSON.parse(row.node_key);
        if (Array.isArray(ref) && typeof ref[0] === 'string' && typeof ref[1] === 'string') topLevelOrders.push({ type: 'task', workspaceKey: ref[0], taskId: ref[1], sortOrder: row.sort_order });
      } catch { /* Historical malformed task-order data is ignored by contract. */ }
    }
    return { groups, members, topLevelOrders };
  }
  async query(input: KnorviaGroupedTaskViewQuery & { provider?: KnorviaProvider }): Promise<KnorviaGroupedTaskView> {
    await this.store.ready(); const all = input.includeAllWorkspaces === true, keys = scopeKeys(input.workspaceScopes);
    const where = ['deleted = 0', 'archived = 0', 'pinned = 0'], args: string[] = [];
    if (!all) { where.push(`workspace_key IN (${keys.map(() => '?').join(', ')})`); args.push(...keys); }
    if (input.provider) { where.push('provider = ?'); args.push(input.provider); }
    const rows = !all && !keys.length ? [] : this.store.all<TaskRow>(fill(SQL.active, where.join(' AND ')), ...args);
    const scopes: TaskScope[] = all ? rows.map(row => ({ workspacePath: row.workspace_path, workspaceIdentity: row.workspace_identity ?? undefined })) : input.workspaceScopes;
    bootstrap(this.store, scopes, rows);
    const visible = new Set(all ? rows.map(row => row.workspace_key) : keys), groups = this.visibleGroups(visible);
    const members = this.store.all<MemberRow>(SQL.members), orders = this.store.all<OrderRow>(SQL.orders);
    const membership = new Map<string, MemberRow>(), byGroup = new Map<string, MemberRow[]>();
    for (const member of members) {
      membership.set(entity(member.workspace_key, member.task_id), member);
      const bucket = byGroup.get(member.group_id) ?? []; bucket.push(member); byGroup.set(member.group_id, bucket);
    }
    const orderMap = new Map(orders.map(row => [row.node_type + ':' + row.node_key, row.sort_order]));
    const active = new Map(rows.map(row => [entity(row.workspace_key, row.task_id), this.tasks.item(row)]));
    const grouped = new Set<string>(), nodes: KnorviaGroupedTaskViewNode[] = [];
    for (const row of groups) {
      const tasks = (byGroup.get(row.group_id) ?? []).map(member => active.get(entity(member.workspace_key, member.task_id))).filter((task): task is KnorviaTaskListItem => Boolean(task));
      if (row.group_id === CRON_DEFAULT_GROUP_ID) tasks.sort((a, b) => b.createdAt - a.createdAt || itemKey(b).localeCompare(itemKey(a)));
      else {
        this.normalizeMembers(row.group_id, tasks, membership);
        tasks.sort((a, b) => (membership.get(itemKey(a))?.sort_order ?? 0) - (membership.get(itemKey(b))?.sort_order ?? 0) || itemKey(a).localeCompare(itemKey(b)));
      }
      for (const task of tasks) grouped.add(itemKey(task));
      const sortOrder = orderMap.get('group:' + row.group_id);
      nodes.push({ type: 'group', group: groupMeta(row), tasks, ...(sortOrder !== undefined ? { sortOrder } : {}) });
    }
    for (const [key, task] of active) {
      if (membership.has(key) || grouped.has(key)) continue;
      const sortOrder = orderMap.get('task:' + taskNode(workspace(task), task.taskId));
      nodes.push({ type: 'task', task, ...(sortOrder !== undefined ? { sortOrder } : {}) });
    }
    this.normalizeTop(nodes, orderMap);
    nodes.sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0) || nodeKey(a).localeCompare(nodeKey(b)));
    return { nodes };
  }
  private normalizeMembers(groupId: string, tasks: KnorviaTaskListItem[], membership: Map<string, MemberRow>): void {
    const missing = tasks.filter(task => membership.get(itemKey(task))?.sort_order === null);
    missing.sort((a, b) => (membership.get(itemKey(b))?.added_at ?? b.createdAt) - (membership.get(itemKey(a))?.added_at ?? a.createdAt) || itemKey(a).localeCompare(itemKey(b)));
    if (!missing.length) return;
    let maximum = this.store.get<{ max_sort_order: number | null }>(SQL.memberMaximum, groupId)?.max_sort_order ?? 0;
    const now = Date.now(), update = this.store.database().prepare(SQL.normalizeMember);
    this.store.transaction(() => {
      for (const task of missing) {
        const member = membership.get(itemKey(task)); if (!member) continue;
        maximum += 1000; update.run(maximum, now, member.workspace_key, member.task_id);
        member.sort_order = maximum; member.updated_at = now;
      }
    });
  }
  private normalizeTop(nodes: KnorviaGroupedTaskViewNode[], orders: Map<string, number>): void {
    const missing = nodes.filter(node => !orders.has(nodeKey(node)));
    const created = (node: KnorviaGroupedTaskViewNode) => node.type === 'group' ? node.group.createdAt : node.task.createdAt;
    missing.sort((a, b) => created(b) - created(a) || nodeKey(a).localeCompare(nodeKey(b)));
    if (!missing.length) return;
    let maximum = this.store.get<{ max_sort_order: number | null }>(SQL.maximum)?.max_sort_order ?? 0;
    const now = Date.now(), insert = this.store.database().prepare(SQL.normalizeOrder);
    this.store.transaction(() => {
      for (const node of missing) {
        maximum += 1000;
        const key = node.type === 'group' ? node.group.id : taskNode(workspace(node.task), node.task.taskId);
        insert.run(node.type, key, maximum, now, now); orders.set(nodeKey(node), maximum); node.sortOrder = maximum;
      }
    });
  }
}

import { randomUUID } from 'node:crypto';
import type { KnorviaTaskGroup, KnorviaTaskGroupColor } from '#src/session/taskListTypes.js';
import { colors, groupMeta, taskNode, workspace } from './model.js';
import type { GroupRow, TaskRef } from './model.js';
import { SQL } from './sql.js';
import { Store } from './store.js';
export class Groups {
  constructor(private store: Store) {}
  initializeTop(ref: TaskRef): boolean {
    const row = this.store.read(ref);
    if (!row || row.deleted === 1 || row.archived === 1 || row.pinned === 1) return false;
    const key = workspace(ref), node = taskNode(key, ref.taskId);
    const member = this.store.get(SQL.hasMember, key, ref.taskId);
    const order = this.store.get(SQL.hasTaskOrder, node);
    if (member || order) return false;
    const now = Date.now(); this.store.database().prepare(SQL.upsertOrder).run('task', node, this.store.nextTop(), now, now);
    return true;
  }
  async initialize(ref: TaskRef): Promise<boolean> { await this.store.ready(); return this.initializeTop(ref); }
  async create(input?: { title?: string; color?: KnorviaTaskGroupColor }): Promise<KnorviaTaskGroup> {
    await this.store.ready(); const now = Date.now(), id = 'task-group-' + randomUUID();
