    return row;
  }
  project(row: TaskRow): KnorviaTaskMeta {
    const identity = row.workspace_identity?.trim();
    const workspaceIdentity = identity === row.workspace_key ? identity : isRemoteWorkspaceIdentity(row.workspace_key) ? row.workspace_key : undefined;
    try {
      const parsed = knorviaTaskMetaSchema.safeParse(JSON.parse(row.meta_json));
      if (parsed.success) return {
        ...parsed.data, taskId: row.task_id, workspacePath: row.workspace_path, workspaceIdentity,
        unreadAt: row.unread_at ?? undefined, cronAutomationId: parsed.data.cronAutomationId ?? row.cron_automation_id ?? undefined,
        offPeakTaskId: parsed.data.offPeakTaskId ?? row.off_peak_task_id ?? undefined, titleOverridden: row.title_overridden === 1,
      };
      logger.warn(undefined, `读取 task index meta_json 非法 taskId=${row.task_id}`, parsed.error.flatten());
    } catch (error) { logger.warn(undefined, `读取 task index meta_json 失败 taskId=${row.task_id}`, error); }
    return {
      taskId: row.task_id, traceId: 'knorvia-' + row.task_id, title: row.title, titleOverridden: row.title_overridden === 1,
      workspacePath: row.workspace_path, workspaceIdentity, createdAt: row.created_at, updatedAt: row.updated_at,
      mode: row.mode as KnorviaTaskMeta['mode'], model: row.model ?? undefined,
      provider: row.provider === KNORVIA_AGENT_PROVIDER ? KNORVIA_AGENT_PROVIDER : undefined,
      migrationSource: row.migration_source ?? undefined, forkedFromTaskId: row.forked_from_task_id ?? undefined,
      cronAutomationId: row.cron_automation_id ?? undefined, offPeakTaskId: row.off_peak_task_id ?? undefined,
      unreadAt: row.unread_at ?? undefined, status: row.task_status ?? undefined,
    };
  }
  write(meta: KnorviaTaskMeta, flags: Flags): KnorviaTaskMeta {
    const searchableText = flags.searchableText !== undefined ? flags.searchableText.slice(0, 200000) : this.read(meta)?.searchable_text ?? '';
    this.database().prepare(SQL.writeTask).run({
      workspace_key: workspace(meta), workspace_path: meta.workspacePath, workspace_identity: meta.workspaceIdentity ?? null,
      task_id: meta.taskId, title: meta.title, task_status: meta.status ?? null, provider: meta.provider ?? null,
      mode: meta.mode, model: meta.model ?? null, migration_source: meta.migrationSource ?? null,
      forked_from_task_id: meta.forkedFromTaskId ?? null, cron_automation_id: meta.cronAutomationId ?? null,
      off_peak_task_id: meta.offPeakTaskId ?? null, created_at: meta.createdAt, updated_at: meta.updatedAt,
      unread_at: meta.unreadAt ?? null, last_unread_at: meta.unreadAt ?? 0,
      pinned: flags.pinned ? 1 : 0, archived: flags.archived ? 1 : 0, deleted: flags.deleted ? 1 : 0,
      title_overridden: flags.titleOverridden ? 1 : 0, write_unread_at: flags.writeUnread ? 1 : 0,
      searchable_text: searchableText, meta_json: JSON.stringify(meta),
    });
    const saved = this.read(meta);
    if (!saved) throw new Error(`task index 写入后缺少 task: ${meta.taskId}`);
    return this.project(saved);
  }
  removeReferences(key: string, id: string): void {
    this.database().prepare(SQL.removeMember).run(key, id);
    this.database().prepare(SQL.removeTaskOrder).run(taskNode(key, id), key);
  }
  nextTop(): number { return (this.get<{ min_sort_order: number | null }>(SQL.minimum)?.min_sort_order ?? 2000) - 1000; }
  systemGroup(ref: TaskRef, id: string, title: string, color: string): void {
    const now = Date.now();
    this.database().prepare(SQL.systemGroup).run(id, title, color, now, now);
    this.database().prepare(SQL.systemOrder).run(id, this.nextTop(), now, now);
    this.database().prepare(SQL.systemMember).run(id, workspace(ref), ref.workspacePath, ref.workspaceIdentity ?? null, ref.taskId, now, now, now);
  }
  offPeak(ref: TaskRef): void {
    if (ref.workspaceIdentity && isRemoteWorkspaceIdentity(ref.workspaceIdentity)) return;
    this.systemGroup(ref, OFF_PEAK_DEFAULT_GROUP_ID, 'off-peak', 'purple');
  }
  private async initialize(path: string): Promise<void> {
    await mkdir(dirname(path), { recursive: true });
    if (!this.db) { this.db = new OpenDatabase(path); this.boundPath = path; }
    this.exec(fill(SQL.busy, String(this.timeout))); this.exec(SQL.foreign);
    const prepared = isTasksStoragePrepared(this.database());
    if (!isTasksStorageMigrated(this.database())) runTasksDatabaseMigrations(this.database());
    this.exec(SQL.wal); this.exec(SQL.normal);
    if (prepared) return;
    if (this.get(SQL.legacyExists)) this.exec(SQL.legacyBackfill);
    for (const row of this.all<Pick<TaskRow, 'workspace_key' | 'workspace_path' | 'workspace_identity' | 'task_id'>>(SQL.offPeakRows)) {
      if (isRemoteWorkspaceIdentity(row.workspace_key)) continue;
      this.offPeak({ workspacePath: row.workspace_path, workspaceIdentity: row.workspace_identity ?? undefined, taskId: row.task_id });
    }
    const deleted = this.all<Pick<TaskRow, 'workspace_key' | 'task_id'>>(SQL.deletedRows);
    if (deleted.length) this.transaction(() => { for (const row of deleted) this.removeReferences(row.workspace_key, row.task_id); });
  }
}

import type { KnorviaProvider, KnorviaTaskMeta } from '@knorvia/shared';
import type { KnorviaTaskListItem, KnorviaTaskListQuery, KnorviaTaskListResult } from '#src/session/taskListTypes.js';
import { workspace, scopeKeys } from './model.js';
import type { ArchiveInput, ListInput, TaskRef, TaskRow } from './model.js';
import { SQL, fill } from './sql.js';
import { Store } from './store.js';
function snippets(text: string, search?: string): string[] {
  if (!search || !text.trim()) return [];
  const needle = search.toLocaleLowerCase(), haystack = text.toLocaleLowerCase();
  const found: string[] = [], windows: Array<[number, number]> = [];
  let cursor = 0;
  while (found.length < 4) {
    const match = haystack.indexOf(needle, cursor);
    if (match < 0) break;
    cursor = match + needle.length;
    const start = Math.max(0, match - 20), end = Math.min(text.length, match + needle.length + 72);
    if (windows.some(([a, b]) => Math.min(b, end) - Math.max(a, start) > 0)) continue;
    const value = ((start > 0 ? '...' : '') + text.slice(start, end) + (end < text.length ? '...' : '')).replace(/\s+/g, ' ').trim().slice(0, 140);
    if (value) { found.push(value); windows.push([start, end]); }
  }
  if (!found.length) { const fallback = text.replace(/\s+/g, ' ').trim().slice(0, 140); if (fallback) found.push(fallback); }
  return found;
}
export class TaskQueries {
  constructor(private store: Store) {}
  item(row: TaskRow, search?: string): KnorviaTaskListItem {
    const meta = this.store.project(row), matches = snippets(row.searchable_text, search);
    return matches.length ? { ...meta, searchSnippet: matches[0], searchSnippets: matches } : meta;
  }
  async get(ref: TaskRef): Promise<KnorviaTaskMeta | null> {
    await this.store.ready(); const row = this.store.read(ref);
    return !row || row.deleted === 1 ? null : this.store.project(row);
  }
  async list(input: ListInput): Promise<KnorviaTaskMeta[]> {
    await this.store.ready();
    const rows = this.store.database().prepare(SQL.list).all({
      workspace_key: input.workspacePath ? workspace({ workspacePath: input.workspacePath, workspaceIdentity: input.workspaceIdentity }) : null,
      include_deleted: input.includeDeleted ? 1 : 0, provider: input.provider ?? null,
      pinned: typeof input.pinned === 'boolean' ? input.pinned ? 1 : 0 : null,
      archived: typeof input.archived === 'boolean' ? input.archived ? 1 : 0 : null,
    }) as TaskRow[];
    return rows.map(row => this.store.project(row));
  }
  async deleted(input: { workspacePath: string; workspaceIdentity?: string; provider?: KnorviaProvider }): Promise<string[]> {
    await this.store.ready();
    const rows = this.store.database().prepare(SQL.deletedIds).all({ workspace_key: workspace(input), provider: input.provider ?? null }) as Array<{ task_id: string }>;
    return rows.map(row => row.task_id);
  }
  async automation(id: string): Promise<KnorviaTaskMeta[]> {
    await this.store.ready();
    return (this.store.database().prepare(SQL.automation).all({ automation_id: id }) as TaskRow[]).map(row => this.store.project(row));
  }
  async query(input: KnorviaTaskListQuery & { provider?: KnorviaProvider }): Promise<KnorviaTaskListResult> {
    await this.store.ready(); const keys = scopeKeys(input.workspaceScopes);
    if (!keys.length) return { items: [], total: 0, hasMore: false };
    const where = ['deleted = 0', `workspace_key IN (${keys.map(() => '?').join(', ')})`];
    const args: Array<string | number> = [...keys];
    if (input.provider) { where.push('provider = ?'); args.push(input.provider); }
    if (input.kind === 'pinned') where.push('pinned = 1', 'archived = 0');
    else if (input.kind === 'archived') where.push('archived = 1');
    else where.push('pinned = 0', 'archived = 0');
    const search = input.search?.trim();
    if (search) { where.push('(LOWER(title) LIKE ? OR LOWER(searchable_text) LIKE ?)'); const like = '%' + search.toLocaleLowerCase() + '%'; args.push(like, like); }
    const condition = where.join(' AND ');
    const total = this.store.get<{ total: number }>(fill(SQL.count, condition), ...args)?.total ?? 0;
    const order = input.sortBy === 'created' ? 'created_at DESC, updated_at DESC, task_id DESC' : 'updated_at DESC, created_at DESC, task_id DESC';
    const limit = typeof input.limit === 'number' && Number.isFinite(input.limit) && input.limit > 0 ? Math.floor(input.limit) : null;
    const rows = this.store.all<TaskRow>(fill(SQL.query, condition, order, limit === null ? '' : ' LIMIT ?'), ...args, ...(limit === null ? [] : [limit]));
    const purposes = new Map(input.workspaceScopes.filter(scope => scope.workspacePurpose).map(scope => [workspace(scope), scope.workspacePurpose]));
    const items = rows.map(row => { const item = this.item(row, search), purpose = purposes.get(row.workspace_key); return purpose ? { ...item, workspacePurpose: purpose } : item; });
    return { items, total, hasMore: total > rows.length };
  }
  async archive(input: ArchiveInput): Promise<KnorviaTaskMeta[]> {
    await this.store.ready();
    const cutoff = Date.now() - Math.max(1, Math.floor(input.olderThanDays)) * 86400000;
    const where = ['workspace_key = ?', 'deleted = 0', 'archived = 0', 'pinned = 0', 'unread_at IS NULL', 'updated_at < ?', "task_status = 'completed'"];
    const args: Array<string | number> = [workspace(input), cutoff];
    if (input.provider) { where.push('provider = ?'); args.push(input.provider); }
    const rows = this.store.all<TaskRow>(fill(SQL.stale, where.join(' AND ')), ...args);
    if (!rows.length) return [];
    const update = this.store.database().prepare(SQL.archive);
    this.store.transaction(() => { for (const row of rows) update.run(row.workspace_key, row.task_id); });
    return rows.map(row => this.store.project(row));
  }
}

import { CRON_DEFAULT_GROUP_ID } from '@knorvia/shared';
import type { KnorviaTaskMeta } from '@knorvia/shared';
import type { AgentInput, StateInput, SyncInput, TaskRef } from './model.js';
import { Store } from './store.js';
import { Groups } from './groups.js';
export class TaskWrites {
  constructor(private store: Store, private groups: Groups) {}
  sync(input: SyncInput): Promise<KnorviaTaskMeta> {
    return this.store.enqueue(input.meta, () => this.syncNow(input));
  }
  syncAtTop(input: SyncInput): Promise<{ meta: KnorviaTaskMeta; initializedGroupedOrder: boolean }> {
    return this.store.enqueue(input.meta, () => this.store.transaction(() => {
      const meta = this.syncNow(input);
      return { meta, initializedGroupedOrder: this.groups.initializeTop(input.meta) };
    }));
  }
  private syncNow(input: SyncInput): KnorviaTaskMeta {
    const row = this.store.read(input.meta);
    const old = row ? this.store.project(row) : undefined;
    const incoming = input.meta;
    const titleOverridden = input.titleOverridden ?? (row?.title_overridden === 1);
    const terminal = old?.status === 'completed' || old?.status === 'error';
    const keepTerminal = terminal && (!incoming.status || incoming.status === 'running') && (old?.updatedAt ?? 0) > incoming.updatedAt;
    const meta: KnorviaTaskMeta = {
      ...incoming, title: titleOverridden && old ? old.title : incoming.title, titleOverridden,
      status: keepTerminal ? old?.status : incoming.status, lastError: keepTerminal ? old?.lastError : incoming.lastError,
      target: Object.prototype.hasOwnProperty.call(incoming, 'target') ? incoming.target : old?.target,
      migrationSource: incoming.migrationSource ?? old?.migrationSource,
      cronAutomationId: incoming.cronAutomationId ?? old?.cronAutomationId,
      offPeakTaskId: incoming.offPeakTaskId ?? old?.offPeakTaskId,
      updatedAt: Math.max(incoming.updatedAt, old?.updatedAt ?? 0), unreadAt: incoming.unreadAt ?? old?.unreadAt,
    };
    const saved = this.store.write(meta, {
      pinned: input.pinned ?? (row?.pinned === 1), archived: input.archived ?? (row?.archived === 1),
      deleted: input.deleted ?? (row?.deleted === 1), titleOverridden, searchableText: input.searchableText,
    });
    if (meta.cronAutomationId && !old?.cronAutomationId) this.store.systemGroup(meta, CRON_DEFAULT_GROUP_ID, 'cron', 'blue');
    if (meta.offPeakTaskId && !old?.offPeakTaskId) this.store.offPeak(meta);
    return saved;
  }
  seed(meta: KnorviaTaskMeta): Promise<KnorviaTaskMeta> {
    return this.store.enqueue(meta, () => {
      const row = this.store.read(meta);
      return row ? this.store.project(row) : this.store.write(meta, { pinned: false, archived: false, deleted: false, titleOverridden: meta.titleOverridden ?? false });
    });
  }
  clearUnread(input: TaskRef & { expectedUnreadAt: number }): Promise<{ meta: KnorviaTaskMeta; cleared: boolean }> {
    return this.store.enqueue(input, () => this.store.transaction(() => {
      const row = this.store.requireRow(input), current = this.store.project(row);
      if (current.unreadAt !== input.expectedUnreadAt) return { meta: current, cleared: false };
      const meta = this.store.write({ ...current, unreadAt: undefined }, {
        pinned: row.pinned === 1, archived: row.archived === 1, deleted: false, titleOverridden: row.title_overridden === 1, writeUnread: true,
      });
      return { meta, cleared: true };
    }));
  }
  deleteArchived(input: TaskRef): Promise<KnorviaTaskMeta | null> {
    return this.store.enqueue(input, () => this.store.transaction(() => {
      const row = this.store.read(input);
      if (!row || row.deleted === 1 || row.archived !== 1) return null;
      const saved = this.store.write(this.store.project(row), {
        pinned: row.pinned === 1, archived: true, deleted: true, titleOverridden: row.title_overridden === 1,
      });
      this.store.removeReferences(row.workspace_key, row.task_id); return saved;
    }));
  }
  update(input: StateInput): Promise<KnorviaTaskMeta> {
    return this.store.enqueue(input, () => {
      const run = () => {
        const row = this.store.requireRow(input), old = this.store.project(row), patch = input.patch;
        const writesUnread = 'unreadAt' in patch;
        const unreadAt = typeof patch.unreadAt === 'number'
          ? Math.max(patch.unreadAt, Math.max(row.last_unread_at, row.unread_at ?? 0, old.unreadAt ?? 0) + 1)
          : writesUnread ? undefined : old.unreadAt;
