      group.run(id, title, color, now, now);
      if (!ordered.has(id)) { maximum += 1000; order.run(id, maximum, now, now); ordered.add(id); }
      rows.forEach((row, index) => {
        removeMember.run(row.workspace_key, row.task_id);
        member.run(id, row.workspace_key, row.workspace_path, row.workspace_identity, row.task_id, (index + 1) * 1000, now, now, now);
        removeOrder.run(taskNode(workspace({ workspacePath: row.workspace_path, workspaceIdentity: row.workspace_identity ?? undefined }), row.task_id));
