type Flags = { pinned: boolean; archived: boolean; deleted: boolean; titleOverridden: boolean; writeUnread?: boolean; searchableText?: string };
export class Store {
  private db?: DatabaseSync;
  private boundPath?: string;
  private initializing?: Promise<void>;
  private writes = new Map<string, Promise<void>>();
  constructor(private startupPath?: string, private timeout = 5000) {}
  async ready(): Promise<void> {
    const path = this.startupPath ?? getTasksIndexDatabasePath();
    if (this.boundPath && this.boundPath !== path) this.close();
    if (!this.initializing) {
      this.initializing = this.initialize(path).catch(error => { this.close(); throw error; });
    }
    await this.initializing;
  }
  close(options?: { throwOnError?: boolean }): void {
    let failure: unknown;
