      workspace_key: workspace(meta), workspace_path: meta.workspacePath, workspace_identity: meta.workspaceIdentity ?? null,
      task_id: meta.taskId, title: meta.title, task_status: meta.status ?? null, provider: meta.provider ?? null,
      mode: meta.mode, model: meta.model ?? null, migration_source: meta.migrationSource ?? null,
      forked_from_task_id: meta.forkedFromTaskId ?? null, cron_automation_id: meta.cronAutomationId ?? null,
      off_peak_task_id: meta.offPeakTaskId ?? null, created_at: meta.createdAt, updated_at: meta.updatedAt,
      unread_at: meta.unreadAt ?? null, last_unread_at: meta.unreadAt ?? 0,
      pinned: flags.pinned ? 1 : 0, archived: flags.archived ? 1 : 0, deleted: flags.deleted ? 1 : 0,
      title_overridden: flags.titleOverridden ? 1 : 0, write_unread_at: flags.writeUnread ? 1 : 0,
      searchable_text: searchableText, meta_json: JSON.stringify(meta),
    });
    const saved = this.read(meta);
    if (!saved) throw new Error(`task index 写入后缺少 task: ${meta.taskId}`);
