        ...old, title: row.title_overridden !== 1 && patch.title ? patch.title : old.title,
        titleOverridden: row.title_overridden === 1, updatedAt: patch.updatedAt ?? old.updatedAt, status: patch.status ?? old.status,
        lastError: 'lastError' in patch ? patch.lastError : old.lastError, target: 'target' in patch ? patch.target : old.target,
      }, { pinned: row.pinned === 1, archived: row.archived === 1, deleted: row.deleted === 1, titleOverridden: row.title_overridden === 1 });
    });
  }
}

import type { KnorviaProvider, KnorviaTaskMeta } from '@knorvia/shared';
