  }
  async initialize(ref: TaskRef): Promise<boolean> { await this.store.ready(); return this.initializeTop(ref); }
  async create(input?: { title?: string; color?: KnorviaTaskGroupColor }): Promise<KnorviaTaskGroup> {
    await this.store.ready(); const now = Date.now(), id = 'task-group-' + randomUUID();
    const title = input?.title?.trim() || 'New Group', color = input?.color ?? 'gray';
    this.store.database().prepare(SQL.createGroup).run(id, title, color, now, now);
    this.store.database().prepare(SQL.upsertOrder).run('group', id, this.store.nextTop(), now, now);
    return { id, title, color, createdAt: now, updatedAt: now };
  }
  async rename(input: { groupId: string; title: string }): Promise<KnorviaTaskGroup> {
