    const result = this.store.database().prepare(SQL.renameGroup).run(title, now, input.groupId);
    if (Number(result.changes) === 0) throw new Error('Task group 不存在，无法重命名');
    const row = this.store.get<GroupRow>(SQL.group, input.groupId);
    if (!row) throw new Error('Task group 重命名后读取失败');
    return groupMeta(row);
  }
  async recolor(input: { groupId: string; color: KnorviaTaskGroupColor }): Promise<KnorviaTaskGroup> {
    await this.store.ready();
    if (!colors.includes(input.color)) throw new Error('Task group 颜色无效');
    const now = Date.now(), result = this.store.database().prepare(SQL.colorGroup).run(input.color, now, input.groupId);
    if (Number(result.changes) === 0) throw new Error('Task group 不存在，无法更新颜色');
    const row = this.store.get<GroupRow>(SQL.group, input.groupId);
    if (!row) throw new Error('Task group 更新颜色后读取失败');
    return groupMeta(row);
  }
  async delete(input: { groupId: string }): Promise<void> {
    await this.store.ready(); this.store.transaction(() => {
      const result = this.store.database().prepare(SQL.deleteGroup).run(input.groupId);
      if (Number(result.changes) === 0) throw new Error('Task group 不存在，无法删除');
      this.store.database().prepare(SQL.deleteGroupOrder).run(input.groupId);
    });
  }
}

import { resolveWorkspaceKey } from '@knorvia/shared';
import type { KnorviaProvider, KnorviaTaskMeta } from '@knorvia/shared';
import type { KnorviaGroupedTaskRef, KnorviaTaskListWorkspaceScope, KnorviaTaskGroup, KnorviaTaskGroupColor } from '#src/session/taskListTypes.js';
