export type MemberRow = { group_id: string; workspace_key: string; workspace_path: string; workspace_identity: string | null; task_id: string; sort_order: number | null; added_at: number; created_at: number; updated_at: number };
export type GroupRow = { group_id: string; title: string; color: string; created_at: number; updated_at: number };
export type OrderRow = { node_type: string; node_key: string; sort_order: number; created_at: number; updated_at: number };
export const BOOTSTRAP_ONCE = '__knorvia_internal_grouped_workspace_bootstrap_once__';
export const colors: readonly KnorviaTaskGroupColor[] = ['gray', 'red', 'orange', 'yellow', 'green', 'blue', 'purple'];
export function color(value: string): KnorviaTaskGroupColor { return colors.find(item => item === value) ?? 'gray'; }
