  deleteArchivedTask(params: KnorviaGroupedTaskRef): Promise<KnorviaTaskMeta | null> { return this.writes.deleteArchived(params); }
  updateTaskState(params: StateInput): Promise<KnorviaTaskMeta> { return this.writes.update(params); }
  applyAgentPatch(params: AgentInput): Promise<KnorviaTaskMeta | null> { return this.writes.agent(params); }
  listTaskMetas(params: ListInput): Promise<KnorviaTaskMeta[]> { return this.tasks.list(params); }
