  createTaskGroup(params?: { title?: string; color?: KnorviaTaskGroupColor }): Promise<KnorviaTaskGroup> { return this.groups.create(params); }
  renameTaskGroup(params: { groupId: string; title: string }): Promise<KnorviaTaskGroup> { return this.groups.rename(params); }
  updateTaskGroupColor(params: { groupId: string; color: KnorviaTaskGroupColor }): Promise<KnorviaTaskGroup> { return this.groups.recolor(params); }
  deleteTaskGroup(params: { groupId: string }): Promise<void> { return this.groups.delete(params); }
