  for (const row of active) { const bucket = byWorkspace.get(row.workspace_key) ?? []; bucket.push(row); byWorkspace.set(row.workspace_key, bucket); }
  const now = Date.now(), marker = store.database().prepare(SQL.marker);
  if (!byWorkspace.size) { marker.run(BOOTSTRAP_ONCE, now, now); return; }
  const ordered = new Set(store.all<{ node_key: string }>(SQL.groupOrderKeys).map(row => row.node_key));
  let maximum = store.get<{ max_sort_order: number | null }>(SQL.maximum)?.max_sort_order ?? 0;
  const group = store.database().prepare(SQL.bootstrapGroup), order = store.database().prepare(SQL.bootstrapOrder);
  const removeMember = store.database().prepare(SQL.bootstrapRemoveMember), member = store.database().prepare(SQL.bootstrapMember);
  const removeOrder = store.database().prepare(SQL.bootstrapRemoveOrder), workspaceMarker = store.database().prepare(SQL.workspaceMarker);
