      for (const group of groups) group.tasks.forEach((row, index) => {
        member.run(group.id, row.workspace_key, row.workspace_path, row.workspace_identity ?? null, row.task_id, (index + 1) * 1000, now, now, now);
      });
      this.store.exec(SQL.removeAllGroupOrders);
